    points = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not points:
        return [row[:] for row in grid]

    # Horizontal bands are identifiable directly: each occupied row is a solid stripe.
    occupied_rows = [r for r, row in enumerate(grid) if any(row)]
    if all(all(v != 0 for v in grid[r]) and len(set(grid[r])) == 1 for r in occupied_rows):
        key = lambda r, c: r
    else:
        # Select the diagonal direction that best groups the marked cells into stripes.
        def coherence(fn):
            bins = {}
            for r, c, _ in points:
                bins[fn(r, c)] = bins.get(fn(r, c), 0) + 1
            return sum(n * n for n in bins.values())
        key = max((lambda r, c: c-r, lambda r, c: r+c), key=coherence)

    bands = {}
    for r, c, color in points:
        q = key(r, c)
        bands.setdefault(q, {})[color] = bands.setdefault(q, {}).get(color, 0) + 1
    period = len(bands)
    phase_colors = {}
    conflicts = {}
    for q, counts in bands.items():
        phase = q % period
        for color, count in counts.items():
            # In case two clues land on one phase, use the shorter/sparser stripe.
            old = conflicts.get(phase)
            if old is None or count < old[0]:
                conflicts[phase] = (count, color)
    phase_colors = {phase: item[1] for phase, item in conflicts.items()}
    all_colors = {v for _, _, v in points}
    unused = [v for v in sorted(all_colors) if v not in phase_colors.values()]
    for phase in range(period):
        if phase not in phase_colors and unused:
            phase_colors[phase] = unused.pop(0)
    # If duplicate-color clues leave additional phases unassigned, extend the known cycle.
    known = [phase_colors[p] for p in range(period) if p in phase_colors]
    for phase in range(period):
        if phase not in phase_colors:
            phase_colors[phase] = known[phase % len(known)]

    return [[phase_colors[key(r, c) % period] for c in range(w)] for r in range(h)]
